def transform(grid):
    if not grid or not grid[0]:
        return grid

    H, W = len(grid), len(grid[0])
    bg = grid[0][0]

    # Identify object color
    c = None
    for r in range(H):
        for c_idx in range(W):
            if grid[r][c_idx] != bg:
                c = grid[r][c_idx]
                break
        if c:
            break

    if c is None:
        return grid

    # Bounding Box of object c
    r_min, r_max, c_min, c_max = H, -1, W, -1
    for r in range(H):
        for c_idx in range(W):
            if grid[r][c_idx] == c:
                if r < r_min: r_min = r
                if r > r_max: r_max = r
                if c_idx < c_min: c_min = c_idx
                if c_idx > c_max: c_max = c_idx

    if r_min == H:
        return grid # No object found (all bg)

    # Calculate Pads
    # Vertical Pad is half the height of the object BBox
    pad_v = (r_max - r_min + 1) // 2
    # Horizontal Pad is half the width, capped at 3
    pad_h = (c_max - c_min + 1) // 2
    if pad_h > 3:
        pad_h = 3

    # Determine Frame Extents
    fr_t = max(0, r_min - pad_v)
    fr_b = min(H - 1, r_max + pad_v)
    fr_l = max(0, c_min - pad_h)
    fr_r = min(W - 1, c_max + pad_h)

    # Initialize new grid with background
    new_grid = [[bg for _ in range(W)] for _ in range(H)]

    # Fill Frame with 3s, preserving object c
    for r in range(fr_t, fr_b + 1):
        for c_idx in range(fr_l, fr_r + 1):
            if grid[r][c_idx] == c:
                new_grid[r][c_idx] = c
            else:
                new_grid[r][c_idx] = 3

    # Determine valid columns for 1s
    # Intersection of columns where c appears
    valid_cols = set()
    for c_idx in range(W):
        for r in range(H):
            if grid[r][c_idx] == c:
                valid_cols.add(c_idx)
                break

    # Fill 1s below Frame, restricted to columns where object c existed
    start_1_r = fr_b + 1
    end_1_r = H - 1

    for r in range(start_1_r, end_1_r + 1):
        for c_idx in range(c_min, c_max + 1):
            if c_idx in valid_cols:
                new_grid[r][c_idx] = 1

    return new_grid
